import os,json,subprocess,hashlib
pg='/home/nonroot/pg_install/v17/bin/postgres'
def sha(p):
 h=hashlib.sha256()
 with open(p,'rb')as f:
  while True:
   b=f.read(1<<20)
   if not b:break
   h.update(b)
 return h.hexdigest()
